SELECT a.FINANCIER_ID, o.ORG_NAME_AR FINANCIER_NAME_AR, a.PROGRAM_VERSION_ID, pv.PROGRAM_CODE, sa.SUPPORT_TYPE_CODE, COUNT(*) APPROVAL_COUNT, SUM(NVL(sa.INSTALLMENT_SUPPORT_NPV,0)) INSTALLMENT_SUPPORT_NPV, SUM(NVL(sa.DOWNPAYMENT_SUPPORT,0)) DOWNPAYMENT_SUPPORT, SUM(NVL(sa.TOTAL_SUPPORT,0)) TOTAL_SUPPORT FROM MFF_SUBSIDY_APPROVALS sa JOIN MFF_APPLICATIONS a ON a.APPLICATION_ID=sa.APPLICATION_ID JOIN MFF_ORGANIZATIONS o ON o.ORG_ID=a.FINANCIER_ID JOIN MFF_PROGRAM_VERSIONS pv ON pv.PROGRAM_VERSION_ID=a.PROGRAM_VERSION_ID GROUP BY a.FINANCIER_ID,o.ORG_NAME_AR,a.PROGRAM_VERSION_ID,pv.PROGRAM_CODE,sa.SUPPORT_TYPE_CODE;
